export const getV1InvestorPortalActivityRetrieveUrl = (params?: V1InvestorPortalActivityRetrieveParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/investor/portal/activity/?${stringifiedParams}` : `/api/v1/investor/portal/activity/`
}

